import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`sponsor-outreach`,heroTitle:`Land sponsor deals in minutes`,heroSubtitle:`Perplexity Computer analyzes your creator profile, identifies sponsor fit, and drafts personalized outreach you can review and send.`,inputUrlCta:`Find sponsor opportunities`,inputUrlPlaceholder:`e.g. instagram.com/yourchannel`,inputUrlPrefill:`Go to {url} and analyze my profile, content themes, audience signals, engagement, and sponsor fit. Then identify brands that are likely to be a good match for my audience and draft personalized outreach. Deliver: 1) A profile summary and positioning angle. 2) A prioritized list of sponsor categories and target brands. 3) Talking points that connect each brand to my audience. 4) Personalized cold outreach emails and follow-up messages. 5) A simple tracker with status, contact notes, and next steps.`,heroOverlaySteps:[`Analyzing your profile, content themes, audience signals, and engagement`,`Identifying sponsor categories and brands that match your audience`,`Drafting personalized pitch emails and follow-up messages`,`Sponsor target list, talking points, and outreach tracker ready`],generatingSteps:[`Visiting {url} to understand your profile, audience, and content themes`,`Designing an agent to identify sponsor categories and target brands`,`Configuring personalized pitch emails, follow-ups, and talking points`,`Packaging the sponsor list, outreach copy, and tracker`],featureSectionTitle:`From profile to sponsor pipeline`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Sheets, Docs, Notion, and creator platforms can feed one workflow so sponsor research and outreach stay organized.`,`Sponsor target lists. Audience positioning. Personalized pitches. Follow-up copy and trackers. Computer gives you outreach that is ready to review and send.`],capabilitySectionTitle:`Your sponsor outreach assistant, on demand`,capabilitySectionSubtitle:`Drop in your profile link, step away, and come back to a sponsor outreach package.`,capabilityCards:[{title:`Profile Positioning`,description:`Computer can summarize your niche, content themes, audience signals, and sponsor fit so your pitch starts with a clear angle.`},{title:`Sponsor Matching`,description:`Computer can identify sponsor categories and target brands that align with your audience and content style.`},{title:`Outreach Drafting`,description:`Computer can draft personalized emails, follow-ups, and talking points that connect each brand to your audience.`},{title:`Connect Your Tools`,description:`Computer can organize sponsor research across Gmail, Sheets, Docs, Notion, and creator platforms.`},{title:`Remember Your Pitch`,description:`Computer can remember your niche, past sponsor notes, and preferred outreach style so every new campaign starts sharper.`},{title:`Track Next Steps`,description:`Computer can turn sponsor targets into a tracker with contact notes, follow-up timing, and next actions.`}]});export{t as default};
